package cli

import (
	"encoding/json"
	"fmt"
	"strings"
)

// hostedRepoBinding is the repo-level "connected to a hosted brain" marker,
// written once by `entire brain connect`. Only non-secrets live here; tokens
// are minted per call (see mintHostedToken). The per-branch
// hosted-target.json (hostedFactsBinding) records which branches have synced.
type hostedRepoBinding struct {
	RepoID  string `json:"repo_id"`
	BaseURL string `json:"base_url"`
}

const hostedRepoBindingFile = "hosted.json"

func writeHostedRepoBinding(brainDir string, binding hostedRepoBinding) error {
	binding.BaseURL = strings.TrimRight(binding.BaseURL, "/")
	data, err := json.Marshal(binding)
	if err != nil {
		return err
	}
	return withBrainWriteLock(brainDir, func() error {
		return writeBrainRelativeFileAtomic(brainDir, hostedRepoBindingFile, append(data, '\n'), 0600)
	})
}

func readHostedRepoBinding(brainDir string) (hostedRepoBinding, bool, error) {
	var binding hostedRepoBinding
	data, present, err := readMemoryStateFile(brainDir, hostedRepoBindingFile, "hosted repo binding", defaultMaxReadBytes)
	if err != nil || !present {
		return binding, false, err
	}
	if err := json.Unmarshal(data, &binding); err != nil {
		return binding, false, fmt.Errorf("invalid hosted repo binding: %w", err)
	}
	binding.BaseURL = strings.TrimRight(binding.BaseURL, "/")
	return binding, true, nil
}

	// "brief" verb (the MCP server passes "mcp:brain_brief").
	surface string
}

type brainShowOptions struct {
	json bool
}

// brainStatusReport is the JSON contract of `status`, grouped by logical
// function: repo/brain identity, which sources exist, the durable-facts layer
// (counts + verification), the semantic layer (provider, coverage, freshness,
// blind spots — the former `stale` and `semantic-audit` commands), and live
// workspace state.
type brainStatusReport struct {
	GeneratedAt time.Time             `json:"generated_at"`
	Repo        brainStatusRepo       `json:"repo"`
	Brain       brainStatusBrain      `json:"brain"`
	Sources     brainStatusSources    `json:"sources"`
	Facts       *brainStatusFacts     `json:"facts,omitempty"`
	Semantic    *brainStatusSemantic  `json:"semantic,omitempty"`
	Retrieval   *brainStatusRetrieval `json:"retrieval,omitempty"`
	// Onboarding is the `setup` progress projection: fact-backfill counters,
	// background watcher health, and instant-phase component freshness. It
	// answers "is the thing setup started still working?" on the surface people
	// already read; doctor remains the deep environment check.
	Onboarding *brainStatusOnboarding `json:"onboarding,omitempty"`
	Memory     map[string]any         `json:"memory,omitempty"`
	Live       brainLiveState         `json:"live"`
	Issues     []memoryHealthIssue    `json:"issues,omitempty"`
	Warnings   []string               `json:"warnings,omitempty"`
	// Manifest is for in-process consumers (brief, overview, regressions). It is
	// deliberately not part of the JSON contract: it duplicates the structured
	// sections above and its session list scales with brain size.
	Manifest *exportManifest `json:"-"`
}

type brainStatusFacts struct {
	Facts     int `json:"facts"`
	Distilled int `json:"distilled"`
	Authored  int `json:"authored"`
	// Imported counts facts brought in from another memory tool. Omitted when
	// zero so it stays additive for existing readers.
	//
	// Without it the origin buckets do not sum: an import of 400 reported
	// facts=400 distilled=0 authored=0, which reads as a corrupt or empty
	// brain. facts.go states that origins must account for the total, and the
	// manifest already carried Imported -- the agent surface simply did not
	// forward it, so status and the brief were the two places that could not
	// explain their own numbers.
	Imported     int            `json:"imported,omitempty"`
	Superseded   int            `json:"superseded"`
	Branches     int            `json:"branches"`
	Proposals    int            `json:"proposals"`
	Verification *verifySummary `json:"verification,omitempty"`
	// MissingBranches names declared fact branches whose on-disk store is
	// absent. Empty in the healthy case, so it is additive for readers.
	MissingBranches []string `json:"missing_branches,omitempty"`
	// Integrity is the manifest-vs-store cross-check. Facts above is what the
	// manifest DECLARES; this says whether the store can produce it. Present
	// only when the store fails the check, so it stays additive for readers
	// and its presence alone means "do not trust the counts above".
	Integrity *factStoreIntegrity `json:"integrity,omitempty"`
}

// Readable is the fact count a reader may actually rely on: the observed
// number when the cross-check found a defect, and the declared number
// otherwise. Callers rendering a count should prefer it over Facts.
func (f *brainStatusFacts) Readable() int {
	if f == nil {
		return 0
	}
	if f.Integrity != nil && !f.Integrity.OK() {
		return f.Integrity.Readable
	}
	return f.Facts
}

