	// re-derive is a forgery and nothing from that head may be merged.
	if err := factmerge.VerifyIdentities(head); err != nil {
		fmt.Fprintf(errW, "hosted sync: branch %s pull-only refused untrustworthy head: %v\n", branch, err)
		return
