	// target; the blind-spot note keys off its absence.
	if err := writeHostedFactsBinding(storage.BrainDir, branch, binding.RepoID, baseURL); err != nil {
		fmt.Fprintf(errW, "hosted sync: record hosted target: %v\n", err)
	}
