12	
13	// hostedPlacement is the slice of the host CLI's `entire repo view --json`
14	// output this plugin needs (entireio/cli#2758): the repo's region-local ULID
15	// and its cell API base URL, both top-level fields.
16	type hostedPlacement struct {
17		RepoID string `json:"repoId"`
18		APIURL string `json:"apiUrl"`
19	}
20	
21	type connectOptions struct {
22		repoID string
23		apiURL string
24	}
25	
26	func newConnectCommand(opts Options) *cobra.Command {
27		var connectOpts connectOptions
28		cmd := &cobra.Command{
29			Use:   "connect",
30			Short: "Bind this repository to its hosted brain explicitly",
31			Long: `connect binds this repository to its hosted brain: it records the repo id and
32	API base URL (non-secrets only — the host CLI's own login mints a fresh token
33	per sync), then runs one immediate sync so the first pull happens right away.
34	
35	Running connect (or the onboarding flow) is the ONLY way a repository starts
36	syncing: by default memories stay local and background triggers never connect
37	a repo on their own. Placement resolves through the host CLI (entire repo
38	view); pass --repo-id and --api-url to bypass resolution — a non-default cell
39	or a staging target. Re-running connect re-joins after 'entire brain
40	disconnect'.`,
41			Args: cobra.NoArgs,
42			RunE: func(cmd *cobra.Command, args []string) error {
43				return runConnect(cmd, opts, connectOpts)
44			},
45		}
46		cmd.Flags().StringVar(&connectOpts.repoID, "repo-id", "", "Hosted repo id (region-local ULID)")
47		cmd.Flags().StringVar(&connectOpts.apiURL, "api-url", "", "Entire API base URL, https://")
48		return cmd
49	}
50	
51	func runConnect(cmd *cobra.Command, opts Options, connectOpts connectOptions) error {
52		ctx := cmd.Context()
53		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, agentSurfaceTarget(opts, nil))
54		if err != nil {
55			return err
56		}
57		if !local {
58			return fmt.Errorf("connect requires a local repository path")
59		}
60		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
61		if err != nil {
62			return err
63		}
64	
65		repoID := strings.TrimSpace(connectOpts.repoID)
66		apiURL := strings.TrimSpace(connectOpts.apiURL)
67		if repoID == "" || apiURL == "" {
68			resolved, placementErr := resolveHostedPlacement(ctx, opts.Runner, repoDir)
69			if placementErr != nil {
70				// An already-connected (or disconnected — the opt-out keeps its
71				// coordinates) repo stays re-connectable without flags: re-connect
72				// means re-sync, not re-resolve.
73				if existing, present, readErr := readHostedRepoBinding(storage.BrainDir); readErr == nil && present && existing.RepoID != "" {
74					resolved = hostedPlacement{RepoID: existing.RepoID, APIURL: existing.BaseURL}
75				} else {
76					return fmt.Errorf("connect: resolve hosted placement (`entire repo view --json`): %w; pass --repo-id and --api-url explicitly", placementErr)
77				}
78			}
79			if repoID == "" {
80				repoID = resolved.RepoID
81			}
82			if apiURL == "" {
83				apiURL = resolved.APIURL
84			}
85		}
86		binding, err := bindHostedRepo(storage.BrainDir, repoID, apiURL)
87		if err != nil {
88			return fmt.Errorf("connect: %w", err)
89		}
90		renderHostedBanner(cmd.OutOrStdout(),
91			"Connected: repo "+binding.RepoID+" is now syncing memories",
92			"Memories sync periodically and at session end. Teammates' memories merge into this repo's local brain.")
93		// Connect doubles as the initial pull so a fresh clone receives team
94		// memories immediately; failures note and never fail the connect.
95		_, err = hostedFactsSyncAndPull(ctx, cmd.ErrOrStderr(), opts, repoDir, storage, hostedSyncBranch(ctx, opts.Runner, repoDir))
96		return err
97	}
98	
99	// normalizeHostedBinding validates the target and strips a quoted /api/v1
100	// suffix. Cell URLs are commonly quoted with that prefix (repo view's apiUrl,
101	// docs examples), but the factsync client appends /api/v1/repos/... itself —
102	// storing the suffix would 404 every sync. OptedOut is false: a fresh binding
103	// is an opt-in.
104	func normalizeHostedBinding(repoID, apiURL string) (hostedRepoBinding, error) {
105		if strings.TrimSpace(repoID) == "" {
106			return hostedRepoBinding{}, fmt.Errorf("hosted repo id is empty")
107		}
108		validated, err := apiurl.Validate(apiURL)
109		if err != nil {
110			return hostedRepoBinding{}, err
111		}
112		return hostedRepoBinding{RepoID: strings.TrimSpace(repoID), BaseURL: strings.TrimSuffix(validated, "/api/v1")}, nil
113	}
114	
115	// bindHostedRepo is the EXPLICIT connect write: it overwrites whatever is
116	// there, including an opt-out — running connect is how the user opts back in.
117	func bindHostedRepo(brainDir, repoID, apiURL string) (hostedRepoBinding, error) {
118		binding, err := normalizeHostedBinding(repoID, apiURL)
119		if err != nil {
120			return hostedRepoBinding{}, err
121		}
122		if err := writeHostedRepoBinding(brainDir, binding); err != nil {
123			return hostedRepoBinding{}, err
124		}
125		return binding, nil
126	}
127	
128	// resolveHostedPlacement shells out to the host CLI for this repo's hosted
129	// placement.
130	func resolveHostedPlacement(ctx context.Context, runner CommandRunner, repoDir string) (hostedPlacement, error) {
131		ctx, cancel := context.WithTimeout(ctx, hostedShellOutTimeout)
132		defer cancel()
133		stdout, _, err := runner.Run(ctx, repoDir, hostEntireBinary, "repo", "view", "--json")
134		if err != nil {
135			return hostedPlacement{}, err
136		}
137		var result hostedPlacement
138		if err := decodeHostCLIJSON(stdout, &result); err != nil {
139			return hostedPlacement{}, fmt.Errorf("parse repo view json: %w", err)
140		}
141		return result, nil
142	}

